/* Send one command to the SSD1306 */
static void SSD1306_WriteCommand(uint8_t command)
{
    uint8_t data[2];

    data[0] = 0x00;
    data[1] = command;

    HAL_I2C_Master_Transmit(
        &hi2c1,
        SSD1306_I2C_ADDR,
        data,
        2,
        HAL_MAX_DELAY
    );
}


/* Initialize the SSD1306 */
void SSD1306_Init(void)
{
    HAL_Delay(100);

    SSD1306_WriteCommand(0xAE); /* Display OFF */

    SSD1306_WriteCommand(0x20); /* Memory addressing mode */
    SSD1306_WriteCommand(0x00); /* Horizontal addressing */

    SSD1306_WriteCommand(0xB0);

    SSD1306_WriteCommand(0xC8); /* COM scan direction */

    SSD1306_WriteCommand(0x00); /* Low column */
    SSD1306_WriteCommand(0x10); /* High column */

    SSD1306_WriteCommand(0x40); /* Start line */

    SSD1306_WriteCommand(0x81); /* Contrast */
    SSD1306_WriteCommand(0x7F);

    SSD1306_WriteCommand(0xA1); /* Segment remap */

    SSD1306_WriteCommand(0xA6); /* Normal display */

    SSD1306_WriteCommand(0xA8); /* Multiplex ratio */
    SSD1306_WriteCommand(0x3F);

    SSD1306_WriteCommand(0xA4); /* Display follows RAM */

    SSD1306_WriteCommand(0xD3); /* Display offset */
    SSD1306_WriteCommand(0x00);

    SSD1306_WriteCommand(0xD5); /* Display clock */
    SSD1306_WriteCommand(0x80);

    SSD1306_WriteCommand(0xD9); /* Pre-charge */
    SSD1306_WriteCommand(0xF1);

    SSD1306_WriteCommand(0xDA); /* COM pins */
    SSD1306_WriteCommand(0x12);

    SSD1306_WriteCommand(0xDB); /* VCOMH */
    SSD1306_WriteCommand(0x40);

    SSD1306_WriteCommand(0x8D); /* Charge pump */
    SSD1306_WriteCommand(0x14);

    SSD1306_WriteCommand(0xAF); /* Display ON */

    SSD1306_Clear();
    SSD1306_UpdateScreen();
}


/* Clear the display buffer */
void SSD1306_Clear(void)
{
    memset(
        SSD1306_Buffer,
        0x00,
        sizeof(SSD1306_Buffer)
    );

    SSD1306_CurrentX = 0;
    SSD1306_CurrentY = 0;
}


/* Set text cursor */
void SSD1306_SetCursor(uint8_t x, uint8_t y)
{
    if (x >= SSD1306_WIDTH)
    {
        x = 0;
    }

    if (y >= 8)
    {
        y = 0;
    }

    SSD1306_CurrentX = x;
    SSD1306_CurrentY = y;
}


/* Write one character into the display buffer */
void SSD1306_WriteChar(char ch)
{
    uint8_t index;

    /* Convert lowercase letters to uppercase */
    if (ch >= 'a' && ch <= 'z')
    {
        ch = ch - 'a' + 'A';
    }

    /* Unsupported characters become spaces */
    if (ch < 32 || ch > 90)
    {
        ch = ' ';
    }

    index = (uint8_t)(ch - 32);

    /*
     * Each character is 5 pixels wide,
     * plus 1 pixel spacing.
     */
    if (SSD1306_CurrentX + 6 >= SSD1306_WIDTH)
    {
        SSD1306_CurrentX = 0;
        SSD1306_CurrentY++;

        if (SSD1306_CurrentY >= 8)
        {
            SSD1306_CurrentY = 0;
        }
    }

    /*
     * Copy character columns into the display buffer.
     */
    for (uint8_t i = 0; i < 5; i++)
    {
        SSD1306_Buffer[
            SSD1306_CurrentY * SSD1306_WIDTH
            + SSD1306_CurrentX
            + i
        ] = Font5x7[index][i];
    }

    /* One blank column between characters */
    SSD1306_Buffer[
        SSD1306_CurrentY * SSD1306_WIDTH
        + SSD1306_CurrentX
        + 5
    ] = 0x00;

    SSD1306_CurrentX += 6;
}


/* Write a string into the display buffer */
void SSD1306_WriteString(char *str)
{
    while (*str != '\0')
    {
        SSD1306_WriteChar(*str);
        str++;
    }
}


/* Send the complete buffer to the OLED */
void SSD1306_UpdateScreen(void)
{
    uint8_t data[129];

    for (uint8_t page = 0; page < 8; page++)
    {
        SSD1306_WriteCommand(0xB0 + page);
        SSD1306_WriteCommand(0x00);
        SSD1306_WriteCommand(0x10);

        data[0] = 0x40;

        memcpy(
            &data[1],
            &SSD1306_Buffer[page * SSD1306_WIDTH],
            SSD1306_WIDTH
        );

        HAL_I2C_Master_Transmit(
            &hi2c1,
            SSD1306_I2C_ADDR,
            data,
            129,
            HAL_MAX_DELAY
        );
    }
}
